custom_css:
/* --- 日落与归途 感谢代码楼里老师们的代码https://discord.com/channels/1291925535324110879/1380392618336194702
感谢尾老师，类名，输入框伪提示词来自尾老师，hy老师的去除思维链箭头，na老师的悬浮底栏和思维链文字自定义，楼层信息自定义，12老师的去思维链背景色。感谢NA老师的去阴影，感谢咩野老师的去除全局阴影.--- */

/* --- 1. 字体导入 --- */
@import url('https://fonts.googleapis.com/css2?family=DotGothic16&display=swap');
@import url("https://fontsapi.zeoseven.com/293/main/result.css");
@import url("https://fontsapi.zeoseven.com/45/main/result.css");
@import url("https://fontsapi.zeoseven.com/249/main/result.css");
@import url("https://fontsapi.zeoseven.com/575/main/result.css");

/* --- 2. 核心颜色与样式变量 --- */
:root {
    --theme-bg: #1c1427;
    --panel-bg-color: rgba(28, 20, 39, 0.85);
    --panel-bg-hover: rgba(58, 30, 50, 0.95);
    --card-bg-ai: rgba(35, 22, 45, 0.85);
    --card-bg-user: rgba(45, 27, 50, 0.85);
    --input-bg: rgba(25, 15, 30, 0.9);
    --text-main: #fdf6e3;
    --text-subtle: #ffb48f;
    --accent-orange: #ff7b54;
    --accent-purple: #9d72ff;
    --accent-white: #ffffff;
    --font-pixel: 'DotGothic16', monospace;
    --font-main: "LXGW WenKai Mono", var(--font-pixel);
    --font-quote: "Long Cang", var(--font-pixel);
    --font-code: "nzgrRuYinZouZhangKai", monospace;
    --font-title: "NanoQyongDaSong A", var(--font-pixel);
}

/* --- 3. 全局样式与去边框去阴影设定 --- */
* { box-shadow: none !important; border: none !important; outline: none !important; }
body { 
    background-color: var(--theme-bg) !important; 
    background-image: linear-gradient(to bottom, rgba(28, 20, 39, 0.7), rgba(45, 27, 50, 0.9));
    background-size: cover; background-position: center; background-attachment: fixed;
    color: var(--text-main); font-family: var(--font-main); font-weight: normal; 
}

/* 左侧纯日文悬浮环境装饰文字 */
body::before {
    content: '終\A点\Aへ\A向\Aか\Aう\A電\A車';
    white-space: pre-wrap; position: fixed; left: 3%; top: 50%; transform: translateY(-50%);
    font-family: var(--font-pixel); font-size: clamp(16px, 2vw, 24px);
    color: var(--accent-orange); opacity: 0.5;
    text-shadow: 2px 2px 0px rgba(0,0,0,0.8);
    pointer-events: none; z-index: 10;
    animation: jp-text-glow 4s infinite alternate steps(10);
}
@keyframes jp-text-glow { 0% { opacity: 0.3; text-shadow: 2px 2px 0px rgba(0,0,0,0.8); } 100% { opacity: 0.8; text-shadow: 2px 2px 0px var(--accent-purple); } }

#sheld, #character_view { background: transparent !important; margin: 0 auto !important; left: 0; right: 0; overflow: visible !important; }
#chat { background: transparent !important; align-items: center !important; padding-bottom: 240px !important; }
h1, h2, h3, h4, .standoutHeader, .inline-drawer-header, .title_restorable { font-family: var(--font-title); color: var(--accent-orange); font-weight: normal; }

/* --- 4. 顶部导航栏 --- */
#top-settings-holder { position:relative; background-color: var(--panel-bg-color); backdrop-filter: blur(8px); overflow: visible !important; }
.drawer-icon.fa-fw::before { content: '' !important; font-size: 0 !important; }
.drawer-icon.fa-fw { width: 35px; height: 40px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: all 0.2s steps(3); image-rendering: pixelated; }
.drawer-icon.fa-fw:hover { transform: translateY(-4px); filter: drop-shadow(0 4px 0px var(--accent-orange)); }

/* 全部导航栏图标统一替换 */
.drawer-icon.fa-sliders, .drawer-icon.fa-plug, .drawer-icon.fa-font, .drawer-icon.fa-book-atlas, 
.drawer-icon.fa-user, .drawer-icon.fa-image, .drawer-icon.fa-panorama, .drawer-icon.fa-cubes, 
.drawer-icon.fa-bars-progress, .drawer-icon.fa-face-smile, .drawer-icon.fa-address-card,
#ai-config-button .drawer-icon, #sys-settings-button .drawer-icon, #advanced-formatting-button .drawer-icon,
#WI-SP-button .drawer-icon, #user-settings-button .drawer-icon, #extensions-settings-button .drawer-icon,
#table_database_settings_drawer .drawer-icon, #persona-management-button .drawer-icon, #character_popup_button .drawer-icon {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260428/ucQf/2048X2048/2026-04-28_143828.png/webp') !important;
}

/* 抽屉与弹窗背景图 */
.drawer-content, dialog.popup .popup-body, #dialogue_popup {
    background-image: linear-gradient(rgba(28, 20, 39, 0.8), rgba(45, 27, 50, 0.9)), url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260428/ggvn/1199X800/fcceaf860bad99e3fce835a9fb108c69.jpg/webp') !important;
    background-size: cover; background-position: center;
    border-radius: 8px !important;
}

/* --- 5. 底部悬浮输入栏 --- */
#send_textarea::placeholder { color: transparent !important; opacity: 0 !important; }
#form_sheld { position: absolute !important; bottom: 25px !important; left: 0; right: 0; display: flex; justify-content: center; z-index: 1000; pointer-events: none; overflow: visible !important; }
#send_form { 
    pointer-events: auto; width: 80% !important; max-width: 800px !important; margin: 0 auto !important; 
    background-color: var(--input-bg) !important; padding: 10px 15px !important; 
    backdrop-filter: blur(10px) !important; position: relative; 
    border-radius: 12px !important; /* 圆润一点以取代生硬边框 */
    animation: form-float-anim 4s infinite alternate ease-in-out;
}
@keyframes form-float-anim { 0% { transform: translateY(0); } 100% { transform: translateY(-5px); } }
#send_form:hover { background-color: var(--panel-bg-hover) !important; }
#send_textarea { clip-path: none !important; background: transparent !important; color: var(--text-main) !important; }

/* 放置在输入框左右两端随风摇曳 */
#send_form::before {
    content: ''; position: absolute; left: -75px; top: -20px; width: 90px; height: 90px;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260428/OjNR/2048X2048/2026-04-28_144140.png/webp');
    background-size: contain; background-repeat: no-repeat; z-index: 50; pointer-events: none;
    animation: swing-decor-left 3s infinite alternate ease-in-out;
}
#send_form::after {
    content: ''; position: absolute; right: -75px; top: -20px; width: 90px; height: 90px;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260428/Xy7F/2048X2048/2026-04-28_144119.png/webp');
    background-size: contain; background-repeat: no-repeat; z-index: 50; pointer-events: none;
    animation: swing-decor-right 3.5s infinite alternate ease-in-out;
}
@keyframes swing-decor-left { 0% { transform: translateY(0) rotate(-3deg); } 100% { transform: translateY(-10px) rotate(5deg); } }
@keyframes swing-decor-right { 0% { transform: translateY(0) rotate(3deg); } 100% { transform: translateY(-12px) rotate(-5deg); } }

/* 伪提示词：自适应屏幕 */
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before { 
    content: '夕暮れのホームで、君の言葉を待っている...'; 
    color: var(--accent-orange); position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); 
    font-family: var(--font-pixel); font-size: clamp(10px, 1.8vw, 15px); pointer-events: none; z-index: 10; 
    white-space: nowrap; letter-spacing: 1px; 
    opacity: 0.7; animation: pixel-blink 2s infinite ease-in-out;
}
@keyframes pixel-blink { 0% { opacity: 0.2; } 50% {opacity: 1;} 100% { opacity: 0.2; } }

#options_button::before, #send_but::before, #send_form #extensionsMenuButton::before, #ai_retry_button::before, #auto_completion_button::before { display: none !important; }
#options_button, #send_but, #send_form #extensionsMenuButton, #ai_retry_button, #auto_completion_button { width: 34px; height: 34px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: all 0.2s steps(2); font-size: 0; background-color: transparent; image-rendering: pixelated; margin: 0 4px; }
#options_button:hover, #send_but:hover, #send_form #extensionsMenuButton:hover, #ai_retry_button:hover, #auto_completion_button:hover { transform: translateY(-3px) scale(1.1); }

/* 底栏功能按钮贴图替换 */
#options_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260428/pMqZ/2048X2048/2026-04-28_143927.png/webp'); }
#send_form #extensionsMenuButton { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260428/q9md/2048X2048/2026-04-28_143800.png/webp'); }
#send_but { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260428/z1Oh/2048X2048/2026-04-28_145725.png/webp'); }
#ai_retry_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260428/pMqZ/2048X2048/2026-04-28_143927.png/webp'); filter: hue-rotate(180deg); }
#auto_completion_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260428/q9md/2048X2048/2026-04-28_143800.png/webp'); filter: hue-rotate(90deg); }

/* --- 6. 核心：消息卡片 --- */
.mes { 
    display: flex; flex-direction: column; 
    padding: 0 !important; 
    margin: 45px auto 120px !important; /* 增加底部间距防止大图被遮挡 */
    width: 85%; max-width: 820px; 
    border-radius: 12px !important; 
    backdrop-filter: blur(5px) !important; overflow: visible !important; position: relative; 
}
.mes[is_user="false"] { background: var(--card-bg-ai) !important; }
.mes[is_user="true"] { background: var(--card-bg-user) !important; }

/* 底部承接框 - 放大至少两倍 */
.mes::after {
    content: ''; position: absolute; bottom: -120px; left: 50%; transform: translateX(-50%);
    width: 260%; height: 160px; 
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260428/9Z4W/2048X2048/2026-04-28_144915.png/webp');
    background-size: contain; background-position: center top; background-repeat: no-repeat;
    z-index: -1; pointer-events: none; opacity: 0.85;
}

.mes .mesAvatarWrapper {
    display: flex; justify-content: center; align-items: center; padding: 0;
    width: 100%; height: 180px !important; min-height: 180px !important;
    background-size: cover; background-position: center; background-repeat: no-repeat;
    position: relative; z-index: 5; overflow: visible !important;
    border-radius: 12px 12px 0 0;
}
.mes[is_user="false"] .mesAvatarWrapper { 
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260428/j3ay/736X414/Gif_photos.jpg/webp'); 
}
.mes[is_user="true"] .mesAvatarWrapper { 
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260428/RsF8/736X414/%E4%B8%8B%E8%BD%BD.jpg/webp'); 
    background-position: bottom center;
}

/* 头像设定 */
.mes .avatar {
    position: absolute; top: 30px; width: 90px; height: 90px; 
    background: #1c1427 !important; 
    padding: 3px !important; 
    border-radius: 8px !important;
    z-index: 30; display: flex !important; align-items: center; justify-content: center;
}
.mes[is_user="false"] .avatar { left: -25px; }
.mes[is_user="true"] .avatar { right: -25px; left: auto; }
.mes .avatar img { width: 100% !important; height: 100% !important; object-fit: cover !important; border-radius: 6px !important; image-rendering: pixelated; }

/* 状态小标签 */
.mes .avatar::after {
    position: absolute; bottom: -15px; right: -30px; padding: 4px 8px;
    background: rgba(30,20,40, 0.9);
    color: var(--accent-orange); font-family: var(--font-pixel); font-size: 11px; font-weight: normal;
    white-space: nowrap; z-index: 40; border-radius: 4px;
}
.mes[is_user="false"] .avatar::after { content: '💬 お話し中...'; }
.mes[is_user="true"] .avatar::after { content: '▶ 思考中...'; right: auto; left: -30px; color: var(--accent-purple); }

.mes .mes_block { padding: 25px 30px 35px 30px !important; position: relative; overflow: visible !important; min-height: 80px !important; z-index: 10; }
.mes .mes_text, .mes_reasoning { background: transparent !important; padding: 0 !important; margin: 0 !important; backdrop-filter: none !important; }

/* --- 思维链日系自定义 --- */
.mes .mes_reasoning_header { background: transparent !important; border-radius: 0; backdrop-filter: none !important; padding: 0 !important; margin-bottom: 12px !important; display: inline-flex !important; align-items: center !important; }
.mes_reasoning_arrow { display: none !important; }
.mes_reasoning_header h4, .mes_reasoning_header_title { font-size: 0 !important; visibility: hidden; }
.mes_reasoning_header h4::before, .mes_reasoning_header_title::before { 
    content: "🚃 路線検索中... [思考経路を開通]"; 
    font-family: var(--font-pixel); font-size: 13px !important; 
    color: var(--accent-purple); visibility: visible; letter-spacing: 1px; 
}
.mes_reasoning { border-left: 4px solid var(--accent-purple) !important; padding-left: 15px !important; margin-bottom: 20px !important; color: var(--text-subtle); font-family: var(--font-quote); font-size: 0.95em; }
.mes .mes_text { line-height: 1.8; color: var(--text-main); font-size: 16px; text-align: justify; }

/* --- 排版与文字特效 --- */
.mes_text h1 { font-family: var(--font-title); color: var(--accent-orange); font-size: 1.8em; text-align: center; position: relative; padding-bottom: 10px; margin: 25px 0 15px 0; font-weight: normal; }
.mes_text h1::before { content: '『 '; color: var(--accent-purple); } .mes_text h1::after { content: ' 』'; color: var(--accent-purple); }
.mes_text h2 { font-family: var(--font-title); color: var(--accent-orange); font-size: 1.5em; padding: 4px 0 4px 15px; border-left: 6px solid var(--accent-purple) !important; margin: 20px 0 10px 0; background: linear-gradient(to right, rgba(157, 114, 255, 0.15) 0%, transparent 100%); font-weight: normal; }
.mes_text em, .mes_text i { font-family: var(--font-quote); font-style: normal !important; color: var(--text-subtle); background: rgba(255, 123, 84, 0.1); padding: 2px 4px; border-radius: 4px; }
.mes_text strong, .mes_text b { font-family: var(--font-main); color: var(--accent-orange); font-weight: normal; text-shadow: 1px 1px 0px rgba(0,0,0,0.5); }
.mes_text blockquote { background-color: rgba(0, 0, 0, 0.2); border-left: 6px solid var(--accent-purple) !important; padding: 12px 18px; margin: 15px 0; font-family: var(--font-quote); color: var(--quote_text_color); border-radius: 4px; }
.mes_text span.quote, .mes_text q, .mes_text .dialogue { font-family: var(--font-quote); color: var(--quote_text_color); }
.mes_text code { font-family: var(--font-code) !important; background-color: rgba(0, 0, 0, 0.5) !important; color: var(--accent-orange) !important; padding: 4px 8px; border-radius: 4px; }

/* --- 角色名与楼层 --- */
.mes .mesAvatarWrapper > .ch_name { display: none !important; }
.mes .mes_block > .ch_name { 
    display: flex !important; position: absolute; 
    top: -200px !important; 
    background: rgba(28, 20, 39, 0.9) !important; 
    padding: 6px 16px !important; 
    z-index: 120; border-radius: 6px;
}
.mes[is_user="false"] .mes_block > .ch_name { left: 20px !important; right: auto !important; }
.mes[is_user="true"] .mes_block > .ch_name { right: 20px !important; left: auto !important; }
.mes .ch_name .name_text { 
    font-family: var(--font-pixel) !important; font-size: 18px !important; 
    color: var(--accent-orange) !important; background: transparent !important; padding: 0 !important; 
}

/* 日系楼层 ID */
.mes .mesIDDisplay {
    position: absolute; top: 185px !important; 
    background: rgba(0,0,0,0.6) !important; 
    color: var(--accent-white) !important; font-size: 12px !important; z-index: 100; 
    padding: 4px 10px !important; white-space: nowrap; line-height: 1 !important; border-radius: 10px !important;
    left: 50% !important; transform: translateX(-50%) !important; right: auto !important; 
    font-family: var(--font-pixel);
}
.mesIDDisplay::before { content: '🎫 切符番号 ['; color: var(--accent-orange); }
.mesIDDisplay::after { content: ']'; color: var(--accent-orange); }
.mes .mes_timer { position: static !important; color: #a894a4 !important; font-size: 11px !important; font-family: var(--font-pixel); background: rgba(0,0,0,0.5); padding: 2px 6px; border-radius: 4px; }

/* --- 编辑与互动按钮 --- */
.mes .mes_buttons, .mes .mes_edit_buttons { flex-direction: row-reverse; gap: 6px; position: static !important; opacity: 0.3; transition: opacity 0.3s; }
.mes:hover .mes_buttons, .mes:hover .mes_edit_buttons { opacity: 1; }
.mes .mes_buttons .mes_button, .mes .mes_edit_buttons .mes_button {
    background-color: rgba(0,0,0,0.3) !important; padding: 0 !important; cursor: pointer;
    height: 28px !important; width: 28px !important; border-radius: 6px !important;
    color: var(--text-main) !important; transition: all 0.2s;
    font-family: "Font Awesome 6 Free", "FontAwesome" !important; font-weight: 900 !important; font-size: 13px !important;
    display: inline-flex !important; align-items: center !important; justify-content: center !important;
}
.mes .mes_buttons .mes_button:hover, .mes .mes_edit_buttons .mes_button:hover { background-color: var(--accent-purple) !important; transform: scale(1.1); }

/* 打字提示器 */
#typing_indicator { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260428/z1Oh/2048X2048/2026-04-28_145725.png/webp') !important; background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important; animation: pixel-bounce 1s infinite alternate ease-in-out; border: none !important; height: 40px !important; width: 40px !important; margin: 10px auto !important; image-rendering: auto; }
#typing_indicator .dot { display: none !important; }
@keyframes pixel-bounce { 0% { transform: translateY(0); } 100% { transform: translateY(-8px); } }

/* --- 全局UI设定 --- */
.standoutHeader, .inline-drawer-header, .title_restorable, #extensions_settings2 > div, #extensions_settings > div, .openai_logit_bias_preset_form, details > summary, div[name*='Toggles'] h4 { background: rgba(0,0,0,0.2) !important; border-radius: 6px !important; padding: 10px 15px !important; margin-bottom: 8px !important; color: var(--accent-orange) !important; font-family: var(--font-pixel); }
input[type="text"], input[type="number"], input[type="search"], textarea, select, .text_pole { background-color: rgba(0,0,0,0.4) !important; color: var(--accent-white) !important; border-radius: 6px !important; padding: 6px !important; font-family: var(--font-pixel); }
input:focus, textarea:focus, select:focus { background-color: rgba(30,20,40,0.8) !important; }
.menu_button { background-color: rgba(0,0,0,0.3) !important; color: var(--text-main) !important; transition: all 0.2s; border-radius: 6px !important; font-family: var(--font-pixel); }
.menu_button:hover { background-color: var(--accent-purple) !important; color: white !important; }
input[type="checkbox"]:checked::before { box-shadow: inset 1em 1em var(--accent-orange) !important; }

dialog.popup { background-color: transparent !important; }
dialog.popup .popup-body::before, #dialogue_popup::before { content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0; background-color: rgba(28, 20, 39, 0.7); z-index: 0; border-radius: 8px; }
dialog.popup .popup-body > *, #dialogue_popup > * { position: relative; z-index: 1; }
.menu_button.active, .menu_button.world_set, .menu_button.fav_on, #left-nav-panel .menu_button.selected { background-color: var(--accent-orange) !important; color: #fff !important; }

input[type="range"]::-webkit-slider-thumb, input[type="range"]::-moz-range-thumb { -webkit-appearance: none !important; appearance: none !important; width: 16px !important; height: 16px !important; background-color: var(--accent-orange) !important; border-radius: 50% !important; cursor: pointer !important; }
.neo-range-slider { background: rgba(255,255,255,0.2) !important; }

/* --- 手机端适配 --- */
@media (max-width: 768px) {
    body::before { display: none; } /* 手机端隐藏侧边日文 */
    #send_form { width: 75% !important; }
    #send_form::before { left: -45px; top: -15px; width: 60px; height: 60px; }
    #send_form::after { right: -45px; top: -15px; width: 60px; height: 60px; }
    #options_button, #send_but, #send_form #extensionsMenuButton, #ai_retry_button, #auto_completion_button {
        width: 28px !important; height: 28px !important; min-width: 28px !important; margin: 0 1px !important;
    }
    .mes { width: 92%; margin-bottom: 160px !important; }
    .mes .mesIDDisplay { font-size: 11px !important; top: 175px !important; }
    .mes[is_user="false"] .avatar { left: -10px; width: 70px; height: 70px; top: 35px; }
